CREATE TABLE itineraries (id uuid PRIMARY KEY, owner_id uuid NOT NULL, title varchar(200) NOT NULL, status varchar(32) NOT NULL CHECK(status IN ('DRAFT','ACCEPTED','COMPLETED','CANCELLED')), start_date date, end_date date, budget_amount numeric(14,2), budget_currency char(3), notes_ciphertext bytea, created_at timestamptz(3) NOT NULL, updated_at timestamptz(3) NOT NULL, deleted_at timestamptz(3), purge_after timestamptz(3), version integer NOT NULL CHECK(version>0), CHECK(end_date IS NULL OR start_date IS NULL OR end_date>=start_date), CHECK((budget_amount IS NULL)=(budget_currency IS NULL)), CHECK(budget_amount IS NULL OR budget_amount>=0));
CREATE INDEX itineraries_owner_status_created_idx ON itineraries(owner_id,status,created_at DESC,id DESC) WHERE deleted_at IS NULL;
CREATE INDEX itineraries_owner_start_idx ON itineraries(owner_id,start_date) WHERE deleted_at IS NULL;
CREATE TABLE itinerary_items (id uuid PRIMARY KEY, itinerary_id uuid NOT NULL REFERENCES itineraries(id) ON DELETE CASCADE, position integer NOT NULL CHECK(position>=0), title varchar(200) NOT NULL, starts_at timestamptz(3), ends_at timestamptz(3), location_reference varchar(500), notes_ciphertext bytea, status varchar(32) NOT NULL CHECK(status IN ('PLANNED','COMPLETED','CANCELLED')), created_at timestamptz(3) NOT NULL, updated_at timestamptz(3) NOT NULL, deleted_at timestamptz(3), version integer NOT NULL CHECK(version>0), CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at));
CREATE UNIQUE INDEX itinerary_items_position_uq ON itinerary_items(itinerary_id,position) WHERE deleted_at IS NULL;
CREATE INDEX itinerary_items_parent_idx ON itinerary_items(itinerary_id,deleted_at);
CREATE TABLE reservations (id uuid PRIMARY KEY, itinerary_id uuid NOT NULL REFERENCES itineraries(id) ON DELETE CASCADE, provider_name varchar(200) NOT NULL, reference_ciphertext bytea, starts_at timestamptz(3), ends_at timestamptz(3), status varchar(32) NOT NULL CHECK(status IN ('PLANNED','CONFIRMED','CANCELLED')), created_at timestamptz(3) NOT NULL, updated_at timestamptz(3) NOT NULL, deleted_at timestamptz(3), version integer NOT NULL CHECK(version>0), CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at));
CREATE INDEX reservations_parent_status_idx ON reservations(itinerary_id,status) WHERE deleted_at IS NULL;
CREATE TABLE travel_checklists (id uuid PRIMARY KEY, itinerary_id uuid NOT NULL REFERENCES itineraries(id) ON DELETE CASCADE, position integer NOT NULL CHECK(position>=0), title varchar(200) NOT NULL, status varchar(32) NOT NULL CHECK(status IN ('PENDING','COMPLETE')), completed_at timestamptz(3), created_at timestamptz(3) NOT NULL, updated_at timestamptz(3) NOT NULL, deleted_at timestamptz(3), version integer NOT NULL CHECK(version>0), CHECK((status='COMPLETE')=(completed_at IS NOT NULL)));
CREATE UNIQUE INDEX travel_checklists_position_uq ON travel_checklists(itinerary_id,position) WHERE deleted_at IS NULL;
CREATE INDEX travel_checklists_parent_idx ON travel_checklists(itinerary_id,deleted_at);
CREATE TABLE outbox_events (event_id uuid PRIMARY KEY,event_type varchar(128) NOT NULL,event_version integer NOT NULL,subject_type varchar(64) NOT NULL,subject_id uuid NOT NULL,subject_version integer NOT NULL,partition_key varchar(128) NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz(3) NOT NULL,available_at timestamptz(3) NOT NULL,published_at timestamptz(3),attempt_count integer NOT NULL DEFAULT 0,last_error_code varchar(64),created_at timestamptz(3) NOT NULL);
CREATE INDEX outbox_available_idx ON outbox_events(available_at,event_id) WHERE published_at IS NULL;
CREATE TABLE inbox_events (consumer_name varchar(64) NOT NULL,event_id uuid NOT NULL,subject_id uuid NOT NULL,subject_version integer NOT NULL,received_at timestamptz(3) NOT NULL,processed_at timestamptz(3),result_code varchar(64) NOT NULL,PRIMARY KEY(consumer_name,event_id));
CREATE INDEX inbox_received_idx ON inbox_events(received_at);
CREATE TABLE dead_letter_events (id uuid PRIMARY KEY,original_event_id uuid NOT NULL,consumer_name varchar(64) NOT NULL,event_type varchar(128) NOT NULL,event_version integer NOT NULL,payload bytea NOT NULL,failure_code varchar(64) NOT NULL,attempt_count integer NOT NULL,first_failed_at timestamptz(3) NOT NULL,last_failed_at timestamptz(3) NOT NULL,resolved_at timestamptz(3),expires_at timestamptz(3) NOT NULL);
CREATE INDEX dead_letter_expires_idx ON dead_letter_events(expires_at);
CREATE TABLE idempotency_records (id uuid PRIMARY KEY,environment varchar(32) NOT NULL,principal_id uuid NOT NULL,service varchar(64) NOT NULL,method varchar(16) NOT NULL,route_template varchar(256) NOT NULL,key_hash varchar(64) NOT NULL,request_hash varchar(64) NOT NULL,state varchar(16) NOT NULL CHECK(state IN ('IN_PROGRESS','COMPLETED')),response_status integer,response_body bytea,response_headers jsonb,created_at timestamptz(3) NOT NULL,completed_at timestamptz(3),expires_at timestamptz(3) NOT NULL,UNIQUE(environment,principal_id,service,method,route_template,key_hash));
CREATE INDEX idempotency_expires_idx ON idempotency_records(expires_at);
